    if (categoryId)
        filter[CATEGORY_ID_FIELD_REST] = { $in: [categoryId] };
    return {
        filter,
        sort: [
            { fieldName: START_DATE_FIELD, order: "ASC" },
            { fieldName: CREATED_DATE_FIELD_REST, order: "DESC" },
