export function formattedAddress(address) {
    if (!address)
        return "";
    if (typeof address.formatted === "string" && address.formatted)
        return address.formatted;
    if (typeof address.formattedAddress === "string" && address.formattedAddress)
        return address.formattedAddress;
    return [address.addressLine1 ?? address.addressLine, address.addressLine2, address.city, address.subdivision, address.postalCode, address.country]
