export async function fetchEventById(eventId: string): Promise<EventDetail | null> {
  try {
    const res = await wixRequest<Raw>(`/events/v3/events/${encodeURIComponent(eventId)}`, { method: "GET", query: { fields: DETAIL_FIELDS } });
