      rsvpValues,
      guestCount,
      guestNames,
      canRsvp: canSubmitRsvp(rsvpForm, rsvpValues, guestCount, true),
      submitting,
      confirmed,
      error,
    };
    return snapshot;
  }

  async function run(op: () => Promise<RegistrationResult>): Promise<RegistrationResult> {
    submitting = true;
    error = null;
    emit();
    try {
