          emit();
        })
        .catch((e) => {
          if (!started) return;
          tiers = [];
          error = errorMessage(e);
          emit();
        });
    },
    stop() {
      started = false;
    },
    setQuantity(tierId, quantity, optionId) {
      const tier = (tiers ?? []).find((t) => t.id === tierId);
